using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ChainedChantingPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Sothis/ChainedChantingPreviewDescription", order = 0)]
public class ChainedChantingPreviewDescription : PreviewDescription
{
	[SerializeField]
	private NonNormalChantingCustomDescription nonNormalChantingCustomDescription;

	public override string GetCustomPreviewDescription(string amountModified, BattleAction battleAction)
	{
		ChainedChantingAction chainedChantingAction = battleAction as ChainedChantingAction;
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedXTimesFormatted(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(nonNormalChantingCustomDescription.ChantingID), chainedChantingAction.GetTimesAmount()).RemoveLast();
	}
}
